//! The built-in code editor: tabs for several files, line numbers, syntax colors, Ctrl+S to save.
use std::path::{Path, PathBuf};

use eframe::egui::{self, vec2, Align2, FontId, Key, Modifiers, RichText, ScrollArea, TextStyle, Ui};

use crate::{syntax, theme::*, widgets::*};

pub struct Doc {
    pub path: PathBuf,
    pub text: String,
    saved: String,
    pub lang: syntax::Lang,
    /// Generated by Oxide: shown, not editable.
    pub readonly: bool,
    pub error: Option<String>,
}

impl Doc {
    pub fn open(path: &Path, readonly: bool) -> Doc {
        let (text, error) = match std::fs::read_to_string(path) {
            Ok(t) => (t, None),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => (String::new(), None),
            Err(e) => (String::new(), Some(format!("Could not read the file: {e}"))),
        };
        Doc { path: path.to_path_buf(), saved: text.clone(), text, lang: syntax::Lang::of(path), readonly, error }
    }

    pub fn dirty(&self) -> bool {
        self.text != self.saved
    }

    pub fn name(&self) -> String {
        self.path.file_name().map(|n| n.to_string_lossy().into_owned()).unwrap_or_default()
    }

    pub fn save(&mut self) -> Result<(), String> {
        if self.readonly {
            return Err("This file is made by Oxide and cannot be edited here.".into());
        }
        if let Some(d) = self.path.parent() {
            let _ = std::fs::create_dir_all(d);
        }
        // a copy of what was there, once, so a bad edit is never the end of the world
        let bak = self.path.with_extension(format!("{}.oxide-bak", self.path.extension().map(|e| e.to_string_lossy().into_owned()).unwrap_or_default()));
        if self.path.exists() && !bak.exists() {
            let _ = std::fs::copy(&self.path, &bak);
        }
        std::fs::write(&self.path, &self.text).map_err(|e| e.to_string())?;
        self.saved = self.text.clone();
        self.error = None;
        Ok(())
    }

    pub fn revert(&mut self) {
        self.text = self.saved.clone();
    }
}

#[derive(Default)]
pub struct Editor {
    pub docs: Vec<Doc>,
    pub current: usize,
    pub message: Option<String>,
}

pub enum Event {
    None,
    /// A file was saved: the caller reloads whatever uses it.
    Saved(PathBuf),
}

impl Editor {
    pub fn open(&mut self, path: &Path, readonly: bool) {
        if let Some(i) = self.docs.iter().position(|d| d.path == path) {
            self.current = i;
            return;
        }
        self.docs.push(Doc::open(path, readonly));
        self.current = self.docs.len() - 1;
    }

    pub fn close(&mut self, i: usize) {
        if i < self.docs.len() {
            self.docs.remove(i);
            self.current = self.current.min(self.docs.len().saturating_sub(1));
        }
    }

    /// Show the editor in the space available. Returns what happened.
    pub fn ui(&mut self, ui: &mut Ui, height: f32) -> Event {
        let mut event = Event::None;
        if self.docs.is_empty() {
            let (rect, _) = ui.allocate_exact_size(vec2(ui.available_width(), height.min(160.0)), egui::Sense::hover());
            ui.painter().rect_filled(rect, radius(8), DEEP());
            ui.painter().text(rect.center(), Align2::CENTER_CENTER, "Open a file from the list above to edit it here.", FontId::proportional(14.0), MUTED());
            return event;
        }
        // tabs
        let mut close: Option<usize> = None;
        ui.horizontal_wrapped(|ui| {
            ui.spacing_mut().item_spacing = vec2(4.0, 4.0);
            for (i, d) in self.docs.iter().enumerate() {
                let sel = i == self.current;
                let label = format!("{}{}", d.name(), if d.dirty() { "  *" } else { "" });
                let btn = egui::Button::new(RichText::new(label).color(if sel { ON_ACCENT() } else { TEXT() }).family(if sel { medium() } else { egui::FontFamily::Proportional }))
                    .fill(if sel { ACCENT() } else { FIELD() })
                    .corner_radius(radius(8));
                let r = ui.add(btn).on_hover_text(d.path.display().to_string());
                if r.clicked() {
                    self.current = i;
                }
                if r.middle_clicked() {
                    close = Some(i);
                }
            }
        });
        if let Some(i) = close {
            self.close(i);
            return event;
        }
        let cur = self.current.min(self.docs.len() - 1);
        let (mut want_save, mut want_close) = (false, false);
        {
            let d = &mut self.docs[cur];
            ui.add_space(4.0);
            ui.horizontal(|ui| {
                ui.label(RichText::new(d.path.display().to_string()).color(MUTED()).size(12.0));
                ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                    if ghost_button(ui, "Close").clicked() {
                        want_close = true;
                    }
                    if !d.readonly {
                        if primary_button(ui, "Save").clicked() {
                            want_save = true;
                        }
                        if ghost_button(ui, "Revert").clicked() {
                            d.revert();
                        }
                    }
                    tag(ui, d.lang.name(), MUTED());
                    if d.readonly {
                        tag(ui, "made by Oxide", WARN());
                    }
                });
            });
            ui.add_space(4.0);
            if ui.input_mut(|i| i.consume_key(Modifiers::COMMAND, Key::S)) {
                want_save = true;
            }

            let font = TextStyle::Monospace.resolve(ui.style());
            let line_h = ui.fonts_mut(|f| f.row_height(&font));
            let lines = d.text.split('\n').count().max(1);
            let gutter = (lines.to_string().len() as f32 + 2.0) * line_h * 0.62;
            let lang = d.lang;
            let readonly = d.readonly;
            egui::Frame::new().fill(DEEP()).stroke(egui::Stroke::new(1.0, BORDER())).corner_radius(radius(8)).inner_margin(egui::Margin::same(6)).show(ui, |ui| {
                ScrollArea::both().min_scrolled_height((height - 70.0).max(160.0)).max_height((height - 70.0).max(160.0)).auto_shrink([false, false]).show(ui, |ui| {
                    ui.horizontal_top(|ui| {
                        // line numbers
                        let (grect, _) = ui.allocate_exact_size(vec2(gutter, line_h * lines as f32), egui::Sense::hover());
                        for n in 0..lines {
                            ui.painter().text(
                                egui::pos2(grect.right() - 6.0, grect.top() + n as f32 * line_h),
                                Align2::RIGHT_TOP,
                                (n + 1).to_string(),
                                font.clone(),
                                MUTED().linear_multiply(0.7),
                            );
                        }
                        let mut layouter = |ui: &Ui, buf: &dyn egui::TextBuffer, _wrap: f32| {
                            let job = syntax::layout_job(buf.as_str(), lang, ui, f32::INFINITY);
                            ui.fonts_mut(|f| f.layout_job(job))
                        };
                        ui.add(
                            egui::TextEdit::multiline(&mut d.text)
                                .font(TextStyle::Monospace)
                                .code_editor()
                                .frame(egui::Frame::NONE)
                                .desired_width(f32::INFINITY)
                                .desired_rows(24)
                                .interactive(!readonly)
                                .layouter(&mut layouter),
                        );
                    });
                });
            });
        }
        if want_save {
            let d = &mut self.docs[cur];
            match d.save() {
                Ok(()) => {
                    self.message = Some(format!("Saved {}", d.name()));
                    event = Event::Saved(d.path.clone());
                }
                Err(e) => self.message = Some(e),
            }
        }
        if want_close {
            self.close(cur);
        }
        event
    }
}
